// string's members: one function per member, each declared by the //kavun:member directive in its doc comment. The
// table, stringMethods, and the member entries of docs/reference/types/string.md (alphabetical, so the order here is
// free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Report truthiness, which is non-emptiness: `!!x` ⟺ `x != string()`.
//
//kavun:member is_true pure () -> bool
func stringIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// ```go
// "hi".format("q")     // => "\"hi\"" — quoted render
// ```
//
//kavun:member format pure ([spec]) -> string
func stringFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Answer the receiver, which as an immutable string already is an independent copy.
//
// On an immutable value `copy`/`freeze` are cheap identity-like operations kept for generic code.
//
//kavun:member copy pure () -> string
func stringCopy(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver, which as a string already is deep-immutable; see [`copy`](#copy).
//
// ```go
// is_immutable("abc")  // => true — free predicate — always, for string
// ```
//
//kavun:member freeze pure () -> string
func stringFreeze(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the symbols from `start` to `end`; bounds **clamp** (contrast `splice`, which raises), negative indices count
// from the end.
//
// `slice` **clamps** out-of-range bounds (reading past the end is harmless); negative indices count from the
// end. Equivalent to `s[start:end]` with a name usable in a chain; offsets are symbols.
//
// ```go
// "hello".slice(1, 3)          // => "el"
// "hello".slice(3, 99)         // => "lo" — clamps
// "hello".slice(-3, -1)        // => "ll"
// ```
//
//kavun:member slice pure ([start[, end]]) -> string
func stringSlice(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	s, e, err := readSliceArgs(id.String(), args)
	if err != nil {
		return Undefined, err
	}
	return v.Slice(s, e)
}

// Answer the receiver: a string is immutable and identity-less, so there is nothing to construct.
//
// The mutable-bodied types copy instead: see [`array()`](array.md#array).
//
//kavun:member string pure ([default]) -> string
func stringString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	// immutable and identity-less, so there is nothing to construct: the receiver IS the
	// independent value. It still takes the trailing default like every other conversion
	// cell, so generic x.string(fallback) code works on a string receiver too.
	return ConvMember(id.String(), stringTypeName, args, true, v)
}

// Re-represent the text as its octets, the UTF-8 encoding.
//
// ```go
// "héllo".bytes().len()  // => 6 — octets — the UTF-8 encoding
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member bytes pure ([default]) -> bytes
func stringBytes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*string)(v.Ptr)
	return ConvMember(id.String(), stringTypeName, args, true, NewBytesValue([]byte(*o), false))
}

// Re-represent the text as `runes`, the O(1)-indexing form.
//
// ```go
// "abc".runes()        // => u"abc" — the O(1)-indexing form
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member runes pure ([default]) -> runes
func stringRunes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*string)(v.Ptr)
	return ConvMember(id.String(), stringTypeName, args, true, NewRunesValue(text.DecodeText(*o), false))
}

// Re-represent the text as an array of its symbols, each a `rune`.
//
// ```go
// "abé".array()        // => ['a', 'b', 'é'] — an array of runes
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member array pure ([default]) -> array
func stringArray(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	t, _ := stringTypeAsArray(v)
	return ConvMember(id.String(), stringTypeName, args, true, NewArrayValue(t, false))
}

// Parse the text as a `bool`: `true`/`false`, `1`/`0`, `t`/`f`, `yes`/`no`, case-insensitive.
//
// ```go
// "Yes".bool()         // => true — true/false, 1/0, t/f, yes/no — case-insensitive
// "maybe".bool()       // Error: conversion
// ```
//
//kavun:member bool pure ([default]) -> bool
func stringBool(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	b, ok := conv.ParseBool(*(*string)(v.Ptr))
	return ConvMember(id.String(), stringTypeName, args, ok, BoolValue(b))
}

// Parse the text as a `float`; bad text raises unless a default is given.
//
// ```go
// "1.5".float()        // => 1.5
// ```
//
//kavun:member float pure ([default]) -> float
func stringFloat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	f, ok := stringTypeAsFloat(v)
	return ConvMember(id.String(), stringTypeName, args, ok, FloatValue(f))
}

// Parse the text as an `int`; bad text raises unless a default is given.
//
// ```go
// "123".int()          // => 123
// "12a".int()          // Error: conversion: cannot convert string to int
// "12a".int(0)         // => 0
// ```
//
//kavun:member int pure ([default]) -> int
func stringInt(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	i, ok := stringTypeAsInt(v)
	return ConvMember(id.String(), stringTypeName, args, ok, IntValue(i))
}

// Parse the text as a `decimal`; bad text raises unless a default is given.
//
//kavun:member decimal pure ([default]) -> decimal
func stringDecimal(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	d, ok := stringTypeAsDecimal(v)
	return ConvMember(id.String(), stringTypeName, args, ok, NewDecimalValue(d))
}

// Parse the text as a `time` in the canonical grammar, as `time(text)` reads it; bad text raises unless a default
// is given.
//
// Any other spelling names its layout: see [`parse_time`](#parse_time).
//
// ```go
// "2026-08-29T00:00:00Z".time().year()   // => 2026
// "nope".time(time())                    // => time("1970-01-01T00:00:00Z") — the default
// ```
//
//kavun:member time pure ([default]) -> time
func stringTime(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return textTimeMember(id.String(), stringTypeName, *(*string)(v.Ptr), args)
}

// Parse the text as a `date` in the strict `YYYY-MM-DD` form, as `date(text)` reads it; bad text raises unless a
// default is given.
//
// Any other spelling names its layout: see [`parse_date`](#parse_date).
//
// ```go
// "2026-08-29".date().day()   // => 29
// ```
//
//kavun:member date pure ([default]) -> date
func stringDate(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return textDateMember(id.String(), stringTypeName, *(*string)(v.Ptr), args)
}

// Parse the text as a `time` under a [layout](time.md#text-layouts); text the layout does not read raises unless a
// default is given.
//
// A malformed layout always raises (`invalid_value`): it is the script's mistake, not the data's. The default
// comes after the layout.
//
// ```go
// "2026-08-29T00:00:00Z".parse_time("iso").year()   // => 2026 — the canonical grammar
// "29/08/2026".parse_time("%d/%m/%Y").day()          // => 29
// "nope".parse_time("iso", time())                   // => time("1970-01-01T00:00:00Z") — the default, after the layout
// ```
//
//kavun:member parse_time pure (layout[, default]) -> time
func stringParseTime(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return textParseTimeMember(id.String(), stringTypeName, *(*string)(v.Ptr), args)
}

// Parse the text as a `date` under a layout; text the layout does not read raises unless a default is given.
//
// `"date"` reads the strict `YYYY-MM-DD` form, any other layout is read as for [`parse_time`](#parse_time) (see
// [date](date.md)); the default comes after the layout.
//
// ```go
// "29/08/2026".parse_date("%d/%m/%Y").month()   // => 8
// ```
//
//kavun:member parse_date pure (layout[, default]) -> date
func stringParseDate(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return textParseDateMember(id.String(), stringTypeName, *(*string)(v.Ptr), args)
}

// Report whether every symbol is a real symbol, with no [octet escapes](#undecodable-octets).
//
// The text is well-formed UTF-8 exactly when this holds.
//
// ```go
// "abc".is_valid()                      // => true
// bytes([97, 255]).string().is_valid()  // => false
// ```
//
//kavun:member is_valid pure () -> bool
func stringIsValid(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*string)(v.Ptr)
	// no escapes anywhere: the text is well-formed UTF-8 end to end
	return BoolValue(text.TextIsValid(*o)), nil
}

// Report whether every octet is below `0x80`, which also means one octet per symbol.
//
// ```go
// "abc".is_ascii()                      // => true
// "abé".is_ascii()                      // => false
// ```
//
//kavun:member is_ascii pure () -> bool
func stringIsASCII(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*string)(v.Ptr)
	return BoolValue(text.IsASCIIText(*o)), nil
}

// Report whether the string has no elements.
//
//kavun:member is_empty pure () -> bool
func stringIsEmpty(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*string)(v.Ptr)
	return BoolValue(len(*o) == 0), nil
}

// Answer the number of elements — symbols, not octets.
//
//kavun:member len pure () -> int
func stringLen(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return IntValue(int64(v.Data)), nil // symbols, not bytes
}

// Map every symbol to lowercase.
//
// ```go
// "héllo".upper()      // => "HÉLLO"
// "HÉLLO".lower()      // => "héllo"
// ```
//
//kavun:member lower pure () -> string
func stringLower(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*string)(v.Ptr)
	return NewStringValue(text.EncodeText(text.MapRunesCase(text.DecodeText(*o), unicode.ToLower))), nil
}

// Map every symbol to uppercase; see [`lower`](#lower).
//
//kavun:member upper pure () -> string
func stringUpper(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*string)(v.Ptr)
	return NewStringValue(text.EncodeText(text.MapRunesCase(text.DecodeText(*o), unicode.ToUpper))), nil
}

// Report whether an element, a run, a member of a set or a predicate match occurs; with no argument, whether any
// element is significant.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// It takes all five readings: element, run, variadic set, predicate, and no-argument (any element outside the blank
// set).
//
// No-argument `contains()` ≡ `any()` asks "any significant content?" — `"   ".contains()` is `false`. The
// contiguous-run query belongs to `contains`: `any`/`all` take no run.
//
// ```go
// "banana".contains("nan")     // => true
// ```
//
//kavun:member contains pure (...x) -> bool
func stringContains(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	// The empty run is contained everywhere, the same answer `in` gives.
	m, err := stringReadMatchArgs(vm, "contains", args)
	if err != nil {
		return Undefined, err
	}
	s := *(*string)(v.Ptr)

	if m.runs != nil {
		for _, p := range m.runs {
			if len(p) == 0 {
				return True, nil
			}
		}
		if len(m.runs) == 1 {
			return BoolValue(text.FindRun(s, m.runs[0], false) >= 0), nil
		}
		for i := 0; i < len(s); {
			if text.RunAt(s[i:], m.runs) > 0 {
				return True, nil
			}
			_, w := text.TextFirst(s[i:])
			i += w
		}
		return False, nil
	}

	for off, i := 0, 0; off < len(s); i++ {
		r, w := text.TextFirst(s[off:])
		off += w
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if hit {
			return True, nil
		}
	}
	return False, nil
}

// Count the matches of an element, a run (non-overlapping occurrences), a set or a predicate; with no argument, the
// significant elements.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// ```go
// "banana".count("na")         // => 2
// ```
//
//kavun:member count pure (...x) -> int
func stringCount(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := stringReadMatchArgs(vm, "count", args)
	if err != nil {
		return Undefined, err
	}
	s := *(*string)(v.Ptr)

	n := int64(0)
	if m.runs != nil {
		if len(m.runs) == 1 && len(m.runs[0]) > 0 && text.TextIsValid(m.runs[0]) {
			return IntValue(int64(strings.Count(s, m.runs[0]))), nil
		}
		for i := 0; i < len(s); {
			if k := text.RunAt(s[i:], m.runs); k > 0 {
				n++
				i += k
			} else {
				_, w := text.TextFirst(s[i:])
				i += w
			}
		}
		return IntValue(n), nil
	}

	for off, i := 0, 0; off < len(s); i++ {
		r, w := text.TextFirst(s[off:])
		off += w
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if hit {
			n++
		}
	}
	return IntValue(n), nil
}

// Keep only the matches of an element, a run, a set or a predicate; with no argument, the significant elements; see
// [`remove`](#remove).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
//kavun:member keep pure (...x) -> string
func stringKeep(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := runesReadMatchArgs(vm, "keep", args, false)
	if err != nil {
		return Undefined, err
	}
	elems := text.DecodeText(*(*string)(v.Ptr))
	out := make([]rune, 0, len(elems))

	if m.runs != nil {
		for i := 0; i < len(elems); {
			if k := seq.RunLengthAt(elems, i, m.runs); k > 0 {
				out = append(out, elems[i:i+k]...)
				i += k
			} else {
				i++
			}
		}
		return NewStringValue(text.EncodeText(out)), nil
	}

	for i, r := range elems {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if hit {
			out = append(out, r)
		}
	}
	return NewStringValue(text.EncodeText(out)), nil
}

// Remove every match of an element, a run, a set or a predicate; with no argument, the elements of the [blank
// set](#the-blank-set).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// `remove` and [`keep`](#keep) are duals over the same readings, and the names say which way each one goes.
//
// `keep(x)` answers the matching symbols, `remove(x)` answers the rest — the direction is in the name; both take
// the full menu and act on every occurrence. With no argument each reads against the blank set the way its own
// verb implies — `keep()` keeps the significant symbols, `remove()` removes the blank ones — so the two land on
// the same answer by two different routes:
//
// ```go
// "a1b2".keep(func(c) { return c >= '0' && c <= '9' })   // => "12"
// "banana".remove("na")        // => "ba"
// " a b ".keep()             // => "ab"
// " a b ".remove()             // => "ab" — removes the blanks — same answer, the other action
// ```
//
//kavun:member remove pure (...x) -> string
func stringRemove(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := runesReadMatchArgs(vm, "remove", args, false)
	if err != nil {
		return Undefined, err
	}
	elems := text.DecodeText(*(*string)(v.Ptr))
	out := make([]rune, 0, len(elems))

	if m.significant {
		for _, r := range elems {
			if !text.IsBlankRune(r) {
				out = append(out, r)
			}
		}
		return NewStringValue(text.EncodeText(out)), nil
	}

	if m.runs != nil {
		for i := 0; i < len(elems); {
			if k := seq.RunLengthAt(elems, i, m.runs); k > 0 {
				i += k
			} else {
				out = append(out, elems[i])
				i++
			}
		}
		return NewStringValue(text.EncodeText(out)), nil
	}

	for i, r := range elems {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if !hit {
			out = append(out, r)
		}
	}
	return NewStringValue(text.EncodeText(out)), nil
}

// Report whether some element matches a value, a set or a predicate; with no argument, whether any element is
// significant.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// `any`/`all` take a value, a function, or nothing — the contiguous-run query belongs to `contains`:
//
// ```go
// "abc".all(func(c) { return c >= 'a' })    // => true
// "abc".any("ab")              // Error: invalid_argument_type: "all/any of a run" has no reading — use contains
// ```
//
//kavun:member any pure (...x) -> bool
func stringAny(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := runesReadMatchArgs(vm, "any", args, true)
	if err != nil {
		return Undefined, err
	}
	for i, r := range text.DecodeText(*(*string)(v.Ptr)) {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if hit {
			return True, nil
		}
	}
	return False, nil
}

// Report whether every element matches a value, a set or a predicate; with no argument, whether every element is
// significant; see [`any`](#any).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
//kavun:member all pure (...x) -> bool
func stringAll(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	// True on the empty string.
	m, err := runesReadMatchArgs(vm, "all", args, true)
	if err != nil {
		return Undefined, err
	}
	for i, r := range text.DecodeText(*(*string)(v.Ptr)) {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if !hit {
			return False, nil
		}
	}
	return True, nil
}

// Add the arguments at the back as whole operands: text spreads as a run, a symbol is one element.
//
// `x.append(a, b)` ≡ `x + a + b`.
//
// Whole operands in order, mixing runs and elements freely: `x.append("ab", 'c')` ≡ `x + "ab" + 'c'`.
//
// ```go
// "x".append("ab", 'c', 98)    // => "xabcb" — 98 is 'b'
// "ab".append(bytes("cd"))     // => "abcd"
// "c".prepend("a", 'b')        // => "abc" — arguments in order, at the front
// ```
//
//kavun:member append pure (...xs) -> string
func stringAppend(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	items, err := stringAddItems("append", args)
	if err != nil {
		return Undefined, err
	}
	return NewStringValue(*(*string)(v.Ptr) + text.EncodeText(items)), nil
}

// Add the arguments at the front as whole operands, in argument order; see [`append`](#append).
//
//kavun:member prepend pure (...xs) -> string
func stringPrepend(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	items, err := stringAddItems("prepend", args)
	if err != nil {
		return Undefined, err
	}
	return NewStringValue(text.EncodeText(items) + *(*string)(v.Ptr)), nil
}

// Add each argument at the back as exactly **one element**; a sequence argument raises, even at length 1.
//
// **Validating**: the refusal is the member's purpose — use it when appending a run would be a bug.
//
// ```go
// "ab".push('c')               // => "abc"
// "ab".push("c")               // Error: invalid_argument_type: push takes one element, never a sequence
// ```
//
//kavun:member push pure (...items) -> string
func stringPush(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	items, err := stringPushItems("push", args)
	if err != nil {
		return Undefined, err
	}
	return NewStringValue(*(*string)(v.Ptr) + text.EncodeText(items)), nil
}

// Add each argument at the front as exactly one element, in argument order; see [`push`](#push).
//
//kavun:member push_first pure (...items) -> string
func stringPushFirst(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	items, err := stringPushItems("push_first", args)
	if err != nil {
		return Undefined, err
	}
	return NewStringValue(text.EncodeText(items) + *(*string)(v.Ptr)), nil
}

// Repeatedly drop the elements at both ends while they belong to the set (the blank set with no argument).
//
// Strip **a set of elements**, repeating while they match. A run argument raises — the anchored-run form is
// `remove_prefix`/`remove_suffix`. No argument trims the [blank set](#the-blank-set).
//
// ```go
// "  hi  ".trim()                     // => "hi"
// "xxhixy".trim('x', 'y')             // => "hi"
// "abhiab".trim("ab")                 // Error: invalid_argument_type: trim takes elements — spell trim('a', 'b')
// ```
//
//kavun:member trim pure (...set) -> string
func stringTrim(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	return stringTrimmed("trim", v, args, true, true)
}

// Drop the leading elements that belong to the set (the blank set with no argument); see [`trim`](#trim).
//
//kavun:member trim_start pure (...set) -> string
func stringTrimStart(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	return stringTrimmed("trim_start", v, args, true, false)
}

// Drop the trailing elements that belong to the set (the blank set with no argument); see [`trim`](#trim).
//
//kavun:member trim_end pure (...set) -> string
func stringTrimEnd(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	return stringTrimmed("trim_end", v, args, false, true)
}

// Report whether the string starts with the element or run, or with any of a set of them.
//
// No predicate reading ("the first symbol satisfies `f`" is `index(f) == 0`).
//
// ```go
