// Call the callback on every element — always a **full pass**, its return value ignored — and return the receiver.
//
// The callback gets the element, or `(index, element)` when it does not accept one argument ([callbacks](#callbacks)).
//
// Early exit is `break`'s job in a `for` loop; returning the receiver lets it chain.
//
// ```go
// io := import("io")
// "abc".for_each(func(c) { io.print(c) })               // prints each symbol, returns "abc"
// ```
//
//kavun:member for_each pure (fn) -> string
func stringForEach(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	cb, err := readElemCallback(vm, "for_each", args)
	if err != nil {
		return Undefined, err
	}
	for i, r := range text.DecodeText(*(*string)(v.Ptr)) {
		if _, err := cb.Call(i, RuneValue(r)); err != nil {
			return Undefined, err
		}
	}
	return v, nil
}

// Answer the first position of a match of an element, a run or a predicate, or `undefined` (the `default` when given)
// on a miss.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// `index` and [`index_last`](#index_last) are the only locators.
//
// A locator miss answers `undefined` — never `-1` — or the trailing default. The position is a symbol offset,
// usable with `s[i]`.
//
// ```go
// "banana".index("na")         // => 2
// "banana".index_last("na")    // => 4
// "banana".index("xy")         // => undefined — miss — never -1
// "banana".index("xy", -1)     // => -1 — explicit default
// "héllo".index('l')           // => 2 — symbol offset, usable with s[i]
// "abc".index(func(c) { return c == 'b' })  // => 1
// "  ab".index()               // => 2 — no argument: first significant symbol
// ```
//
//kavun:member index pure ([x[, default]]) -> int
func stringIndex(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	return stringLocate(vm, "index", v, args, false)
}

// Answer the last position of a match, or `undefined` (the `default` when given) on a miss; see [`index`](#index).
//
//kavun:member index_last pure ([x[, default]]) -> int
func stringIndexLast(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	return stringLocate(vm, "index_last", v, args, true)
}

// Concatenate the string with itself `n` times; `s * n` is the operator form.
//
// `n` must be a non-negative whole number (`2.0` converts, `1.5` raises). `s * n` is the operator form — same
// count slot, same errors. There is no reflected `n * s`, and a result past `4294967296` symbols raises rather
// than exhausting the host.
//
// ```go
// "ab".repeat(3)               // => "ababab"
// "ab" * 3                     // => "ababab" — the operator form
// "-" * 40                     // => "----------------------------------------"
// 3 * "ab"                     // Error: invalid_binary_operator: int * string — no reflected direction
// "ab".repeat(1.5)             // Error: invalid_value: whole number required — never silent truncation
// ```
//
//kavun:member repeat pure (n) -> string
func stringRepeat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*string)(v.Ptr)
	n, err := parseRepeatCount(name, args)
	if err != nil {
		return Undefined, err
	}
	if _, err := seq.RepeatTotal(name, n, len(*o)); err != nil {
		return Undefined, err
	}
	return NewStringValue(strings.Repeat(*o, n)), nil
}

// Split the text into an array of the pieces between the separators.
//
// Separators take the menu: element, run, homogeneous set, element-level predicate, or absent (the blank set).
// **`split` has no limit argument.**
//
// Two regimes, deliberately different:
//
// - An **explicit separator** keeps empty pieces — n hits make n+1 pieces, so `"".split(",")` is `[""]`.
// - The **no-argument form** yields the maximal runs of significant content — empties never appear, and
// splitting pure filler yields `[]`.
// - An empty-run separator matches nothing: `"ab".split("")` is `["ab"]`.
//
// ```go
// "a,b,,c".split(',')          // => ["a", "b", "", "c"] — empties kept
// "a::b::c".split("::")        // => ["a", "b", "c"]
// "a,b;c".split(',', ';')      // => ["a", "b", "c"] — separator set
// "a1b2c".split(func(c) { return c >= '0' && c <= '9' })  // => ["a", "b", "c"]
// "  a  b\tc ".split()         // => ["a", "b", "c"] — blank set, maximal runs
// "   ".split()                // => []
// "".split(",")                // => [""]
// ```
//
//kavun:member split pure (...seps) -> array
func stringSplit(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "split"
	elems := text.DecodeText(*(*string)(v.Ptr))

	if len(args) == 0 {
		var pieces []Value
		start := -1
		for i, e := range elems {
			if text.IsBlankRune(e) {
				if start >= 0 {
					pieces = append(pieces, stringPiece(elems[start:i]))
					start = -1
				}
			} else if start < 0 {
				start = i
			}
		}
		if start >= 0 {
			pieces = append(pieces, stringPiece(elems[start:]))
		}
		return NewArrayValue(pieces, false), nil
	}

	pieces := make([]Value, 0, 4)
	start := 0

	if args[0].IsCallable() {
		if len(args) > 1 {
			return Undefined, seq.ErrPredicateAmongMany(name)
		}
		cb, err := newElemCallback(vm, name, args[0])
		if err != nil {
			return Undefined, err
		}
		for i, e := range elems {
			res, err := cb.Call(i, RuneValue(e))
			if err != nil {
				return Undefined, err
			}
			hit, err := res.IsTrue()
			if err != nil {
				return Undefined, err
			}
			if hit {
				pieces = append(pieces, stringPiece(elems[start:i]))
				start = i + 1
			}
		}
		pieces = append(pieces, stringPiece(elems[start:]))
		return NewArrayValue(pieces, false), nil
	}

	runs, err := stringReadRunSet(name, args, "one reading per call (a function among several arguments always raises)")
	if err != nil {
		return Undefined, err
	}
	for i := 0; i < len(elems); {
		if k := seq.RunLengthAt(elems, i, runs); k > 0 {
			pieces = append(pieces, stringPiece(elems[start:i]))
			i += k
			start = i
		} else {
			i++
		}
	}
	pieces = append(pieces, stringPiece(elems[start:]))
	return NewArrayValue(pieces, false), nil
}

// Split at the first separator hit into exactly three pieces, `[before, sep, after]`.
//
// `partition` answers exactly three pieces, `[before, sep, after]`, splitting at the first hit; a miss answers
// `[s, "", ""]`. With no argument the separator is the whole first maximal run of blank filler. Separators take
// the same menu as [`split`](#split).
//
// ```go
// "key=value=x".partition('=')     // => ["key", "=", "value=x"]
// "abc".partition('=')             // => ["abc", "", ""]
// "key  value rest".partition()    // => ["key", "  ", "value rest"]
// ```
//
//kavun:member partition pure (...seps) -> array
func stringPartition(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	// The separator at the first hit is the longest run at that position.
	const name = "partition"
	elems := text.DecodeText(*(*string)(v.Ptr))
	found, n := -1, 0

	switch {
	case len(args) == 0:
		for i, e := range elems {
			if text.IsBlankRune(e) {
				found, n = i, 1
				for found+n < len(elems) && text.IsBlankRune(elems[found+n]) {
					n++
				}
				break
			}
		}

	case args[0].IsCallable():
		if len(args) > 1 {
			return Undefined, seq.ErrPredicateAmongMany(name)
		}
		cb, err := newElemCallback(vm, name, args[0])
		if err != nil {
			return Undefined, err
		}
		for i, e := range elems {
			res, err := cb.Call(i, RuneValue(e))
			if err != nil {
				return Undefined, err
			}
			hit, err := res.IsTrue()
			if err != nil {
				return Undefined, err
			}
			if hit {
				found, n = i, 1
				break
			}
		}

	default:
		runs, err := stringReadRunSet(name, args, "one reading per call (a function among several arguments always raises)")
		if err != nil {
			return Undefined, err
		}
		for i := range elems {
			if k := seq.RunLengthAt(elems, i, runs); k > 0 {
				found, n = i, k
				break
			}
		}
	}

	if found < 0 {
		return NewArrayValue([]Value{stringPiece(elems), stringPiece(nil), stringPiece(nil)}, false), nil
	}
	return NewArrayValue([]Value{stringPiece(elems[:found]), stringPiece(elems[found : found+n]), stringPiece(elems[found+n:])}, false), nil
}

// Split the text into an array of its lines at `\n`, `\r\n` or `\r`; a trailing line break adds no empty last line.
//
// ```go
// "a\nb\r\nc\n".split_lines()  // => ["a", "b", "c"]
// ```
//
//kavun:member split_lines pure () -> array
func stringSplitLines(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "split_lines"
	o := (*string)(v.Ptr)
	pieces := text.SplitLinesString(*o)
	arr := make([]Value, len(pieces))
	for i, p := range pieces {
		arr[i] = NewStringValue(p)
	}
	return NewArrayValue(arr, false), nil
}

// Parse the text as a duration in nanoseconds, in Go's duration grammar (`"300ms"`, `"-1.5h"`).
//
// ```go
// "1h30m".nanoseconds()    // => 5400000000000 — a duration, in Go's duration grammar ("300ms", "-1.5h")
// "later".nanoseconds(0)   // => 0
// ```
//
//kavun:member nanoseconds pure ([default]) -> int
func stringNanoseconds(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	d, err := time.ParseDuration(*(*string)(v.Ptr))
	return ConvMember(id.String(), stringTypeName, args, err == nil, IntValue(int64(d)))
}
